#!/bin/sh
# fix_linux_build.sh - make the AT32IDE-generated build files usable on Linux.
#
# The project was created on Windows, so the generated makefiles under Debug/
# carry a Windows project path glued onto the toolchain path, e.g.
#
#   /home/yiz/AT32IDE_V1.0.15_Linux-X86_64/D:/AT32/Workspace/Lanetum_AFE_Boot/project/src/flash.c
#
# make then reads that "D:" as a rule separator and fails with
# "target pattern contains no '%'".  The post-build step also calls the Windows
# signer, which cannot run here; tools/fwsign is the Linux build of it.
#
# Debug/ is git-ignored and regenerated by the IDE, so re-run this after a
# regeneration.  Usage:
#
#   ./tools/fix_linux_build.sh [project-root]
#
# Default project root is the directory two levels up from this script.

set -e

here=$(cd "$(dirname "$0")" && pwd)
root=${1:-$(cd "$here/../../.." && pwd)}
dbg="$root/project/AT32_IDE/Debug"

[ -d "$dbg" ] || { echo "no Debug directory at $dbg" >&2; exit 1; }

# 1. Point the generated makefiles at the real project root.  The broken form is
#    <toolchain-prefix>/D:/<windows-path>; replace the whole thing.
find "$dbg" -name '*.mk' -o -name 'makefile' | while read -r f; do
    sed -i -E "s#[^[:space:]]*/D:/[^[:space:]]*/project#$root/project#g" "$f"
done

# 2. Use the Linux signer.
sed -i 's#tools/fwsign\.exe#tools/fwsign#g' "$dbg/makefile" 2>/dev/null || true

# 3. Build the signer if it is missing.
if [ ! -x "$root/project/AT32_IDE/tools/fwsign" ]; then
    cc -O2 -std=gnu11 -Wno-deprecated-declarations \
       -o "$root/project/AT32_IDE/tools/fwsign" \
       "$root/project/AT32_IDE/tools/fwsign.c" -lcrypto
    echo "built tools/fwsign"
fi

leftover=$(grep -rl 'D:/' "$dbg" --include='*.mk' --include='makefile' 2>/dev/null | wc -l)
if [ "$leftover" -ne 0 ]; then
    echo "warning: $leftover build file(s) still contain a Windows path" >&2
fi

echo "build files patched for Linux"
